def make_svg_icon(icon_b64, size=28):
    """Build a folium DivIcon that renders a base64 SVG at a given pixel size."""
    html = f'''<img src="data:image/svg+xml;base64,{icon_b64}" style="width:{size}px;height:{size}px;" />'''
    return folium.DivIcon(html=html, icon_size=(size, size), icon_anchor=(size//2, size//2))

