# Max allowed connections per FDH capacity tier
FDH_MAX_CONNECTIONS = {
    144: 320,
    288: 520,
    # add more capacity tiers here if you have them, e.g.
    # 576: 1040,
}

def get_max_connections(capacity):
    """Look up max allowed connections for a given FDH capacity."""
    try:
        cap_int = int(float(capacity))
    except (TypeError, ValueError):
        return 0
    return FDH_MAX_CONNECTIONS.get(cap_int, cap_int)  # fallback = raw capacity if unknown

