# ── Layer Styles ──
# Preferred category field per style key — checked FIRST before falling back to generic candidates
STYLE_FIELD_PRIORITY = {
    "units": ["type"],
    "cmo": ["name"],
    "basemap": ["category"],
    "boundary": ["type"],
    "distribution_cable": ["cable_capacity"],
    "feeder_cable": ["cable_capacity"],
    "splice_closure": ["splicetype"],
    "feeder_splice": ["splicetype"],
    "dktcc_structure": ["type"],
    "structure": ["type"],
}

GENERIC_CANDIDATE_FIELDS = ["cable_capacity","cable_type","type","category",
                            "structure_type","splicetype","fiber_count","name"]

def resolve_cat_value(style_key, lower_props):
    """Find the category value for a feature, using the layer's preferred field first."""
    preferred = STYLE_FIELD_PRIORITY.get(style_key, [])
    for field in preferred:
        if field in lower_props and lower_props[field] not in (None, ""):
            return str(lower_props[field]).strip()
    for field in GENERIC_CANDIDATE_FIELDS:
        if field in lower_props and lower_props[field] not in (None, ""):
            return str(lower_props[field]).strip()
    return None
