# ── Helpers ──
def normalize_col_name(col):
    return str(col).lower().replace(" ","").replace("_","").replace("-","").strip()

def norm_text(x):
    return str(x).lower().replace(" ","").replace("_","").replace("-","").strip()

def norm_fdh(x):
    if pd.isna(x): return ""
    text = str(x).strip().upper()
    text = text.replace("FDH","").replace("-","").replace("_","").replace(" ","")
    nums = re.findall(r"\d+", text)
    return str(int(nums[0])) if nums else text.strip()

def get_col(df, *names):
    if df is None or df.empty: return None
    columns = list(df.columns)
    for name in names:
        if name in columns: return name
    lower_map = {str(c).lower(): c for c in columns}
    for name in names:
        if str(name).lower() in lower_map: return lower_map[str(name).lower()]
    nmap = {normalize_col_name(c): c for c in columns}
    for name in names:
        k = normalize_col_name(name)
        if k in nmap: return nmap[k]
    return None

def find_fdh_column(df):
    if df is None or df.empty: return None
    for col in ["FDH_Name","FDH_NAME","FDH_No","fdh_name","fdh_no","fdh"]:
        r = get_col(df, col)
        if r: return r
    for col in df.columns:
        if "fdh" in col.lower(): return col
    return None

def filter_by_fdh(df, sel):
    if df is None or df.empty: return pd.DataFrame()
    if sel == "All": return df
    col = find_fdh_column(df)
    if col is None: return df.iloc[0:0]
    tmp = df.copy()
    tmp["_F"] = tmp[col].apply(norm_fdh)
    return tmp[tmp["_F"] == norm_fdh(sel)].drop(columns=["_F"], errors="ignore")

def is_file_safe(path):
    return not os.path.exists(path + "-wal")

def get_layer_style_key(gpkg, layer):
    c = (gpkg + " " + layer).lower()
    if "basemap" in c: return "basemap"
    if "boundary" in c: return "boundary"
    if "feeder" in c and "splice" in c: return "feeder_splice"
    if "feeder" in c: return "feeder_cable"
    if "splice" in c or "spc" in c: return "splice_closure"
    if "distribution" in c or "cable" in c: return "distribution_cable"
    if "dktcc" in c: return "dktcc_structure"
    if "structure" in c or "new_structure" in c: return "structure"
    if "unit" in c: return "units"
    if "cmo" in c: return "cmo"
    if "duct" in c: return "duct"
    return "default"

def get_style_for_feature(style_key, feature_props, geom_type):
    styles = LAYER_STYLES.get(style_key, {})
    lower_props = {str(k).lower(): v for k, v in feature_props.items()}
    cat_value = resolve_cat_value(style_key, lower_props)
    style = styles.get(cat_value, styles.get("default", {}))
    if "Line" in geom_type or "line" in geom_type:
        return {"color":style.get("color","#3388ff"),"weight":style.get("weight",2),
                "dashArray":style.get("dash_array",None),"opacity":0.9}
    if "Polygon" in geom_type or "polygon" in geom_type:
        return {"color":style.get("color","#232323"),"weight":style.get("weight",1),
                "fillColor":style.get("fill_color",style.get("color","#3388ff")),
                "fillOpacity":style.get("fill_opacity",0.3),
                "dashArray":style.get("dash_array",None)}
    return {"color":style.get("color","#3388ff")}

