def build_layer_summary_postgis():
    """
    Build a simple layer summary from PostGIS tables.
    """
    raw_dfs = load_all_postgis()
    records = []

    for display_name, old_key in POSTGIS_LAYER_OPTIONS:
        loader_key = pg_key(old_key)
        table_name = get_table_name(loader_key)
        df = raw_dfs.get(loader_key, pd.DataFrame())

        records.append({
            "GeoPackage": display_name,
            "Original_File": table_name if table_name else loader_key,
            "Layer": old_key,
            "Geometry_Type": "PostGIS Geometry",
            "Feature_Count": len(df) if df is not None else 0,
            "CRS": "PostGIS",
        })

    return pd.DataFrame(records)

