# ── Read GPKG ──
@st.cache_data
def read_gpkg(gpkg_name):
    path = os.path.join(DATA_FOLDER, gpkg_name)
    if not os.path.exists(path): return pd.DataFrame()
    if not is_file_safe(path):
        st.warning(f"⚠️ {gpkg_name} is open in QGIS. Save first then click Reload.")
        return pd.DataFrame()
    tables = []
    try:
        for layer in fiona.listlayers(path):
            try:
                gdf = gpd.read_file(path, layer=layer, engine="pyogrio")
                if gdf.empty: continue
                df = gdf.drop(columns=[c for c in ["geometry","geom"] if c in gdf.columns], errors="ignore")
                df["Source_Layer"] = layer
                tables.append(df)
            except: pass
    except: pass
    return pd.concat(tables, ignore_index=True) if tables else pd.DataFrame()

@st.cache_data
def load_all_gpkg_backup():
    return {
        "basemap":         read_gpkg("Basemap.gpkg"),
        "boundary":        read_gpkg("Boundary.gpkg"),
        "dist_cables":     read_gpkg("Cables.gpkg"),
        "dist_splice":     read_gpkg("Distribution_Splicer.gpkg"),
        "dktcc_structure": read_gpkg("DKTCC_Structure.gpkg"),
        "new_ducts":       read_gpkg("Ducts.gpkg"),
        "feeder":          read_gpkg("Feeder.gpkg"),
        "feeder_splice":   read_gpkg("Feeder_Splicers.gpkg"),
        "new_structure":   read_gpkg("New_Structure.gpkg"),
        "units":           read_gpkg("Units.gpkg"),
    }


# Generic reader used by map, layer data and reports (reads from PostGIS tables)
@st.cache_data(show_spinner=False, ttl=120)
def read_layer_geom(path, layer):
    """
    Read a map layer from PostGIS. The 'path' argument is kept only so old code
    that calls this function with a file path does not break.
    """
    loader_key = pg_key(layer)
    table_name = get_table_name(loader_key)

    if not table_name:
        # return empty GeoDataFrame when no mapping exists
        return gpd.GeoDataFrame()

    gdf = read_geotable(table_name)

    if gdf.empty:
        return gdf

    try:
        if gdf.crs and getattr(gdf.crs, 'to_epsg', lambda: None)() != 4326:
            gdf = gdf.to_crs(epsg=4326)
    except Exception:
        pass

    if not gdf.empty and 'geometry' in gdf.columns:
        try:
            gdf['geometry'] = gdf['geometry'].simplify(tolerance=0.00003, preserve_topology=True)
        except Exception:
            pass

    return gdf

